fn heap_push(mut h []i64, is_max bool, x i64) { h << x; mut i:=h.len-1;for i>0{p:=(i-1)/2;bad:=if is_max{h[p]<h[i]}else{h[p]>h[i]};if !bad{break};h[p],h[i]=h[i],h[p];i=p} }
fn heap_pop(mut h []i64,is_max bool)i64{x:=h[0];last:=h.pop();if h.len>0{h[0]=last;mut i:=0;for{l:=2*i+1;r:=l+1;mut b:=i;if l<h.len&&(if is_max{h[l]>h[b]}else{h[l]<h[b]}){b=l};if r<h.len&&(if is_max{h[r]>h[b]}else{h[r]<h[b]}){b=r};if b==i{break};h[i],h[b]=h[b],h[i];i=b}};return x}
fn store_i64_le(mut out &u8,pos int,x i64){u:=u64(x);for b in 0..8{unsafe{out[pos+b]=u8((u>>(8*b))&255)}}}
@[export:'median_of_running_array_integer']
pub fn median_of_running_array_integer(input &i64,length usize,mut output &u8,capacity usize)i64{if unsafe{input==nil}||length<2{return -1};unsafe{n0:=input[0];if n0<1||n0>256||int(length)!=int(n0)+1{return -1};n:=int(n0);for i in 0..n{if input[i+1]<-1_000_000||input[i+1]>1_000_000{return -1}};if output==nil||capacity<usize(n*8){return -2};mut lo:=[]i64{cap:n};mut hi:=[]i64{cap:n};for i in 0..n{x:=input[i+1];if hi.len>0&&x<hi[0]{heap_push(mut lo,true,x)}else{heap_push(mut hi,false,x)};if lo.len>hi.len+1{heap_push(mut hi,false,heap_pop(mut lo,true))}else if hi.len>lo.len+1{heap_push(mut lo,true,heap_pop(mut hi,false))};med:=if lo.len==hi.len{(lo[0]+hi[0])/2}else if lo.len>hi.len{lo[0]}else{hi[0]};store_i64_le(mut output,i*8,med)};return i64(n*8)}}
